from pathlib import Path
def edit(name,old,new):
    p=Path(name);s=p.read_text(encoding='utf-8')
    if old not in s:raise RuntimeError(name+' missing '+old[:45])
    p.write_text(s.replace(old,new),encoding='utf-8')

edit('shared/operations.jsx','function ReadTable({rows,columns,name})','function ReadTable({rows,columns,name,sort,onSort})')
edit('shared/operations.jsx','scope="col">{c.label}</th>','scope="col" aria-sort={sort?.key===c.key?(sort.desc?\'descending\':\'ascending\'):undefined}>{onSort&&[\'time\',\'username\',\'path\',\'status\',\'kind\',\'severity\',\'updated_at\',\'type\',\'client_id\',\'ip_address\',\'error\'].includes(c.key)?<button onClick={()=>onSort(c.key)}>{c.label}<span aria-hidden="true">{sort?.key===c.key?(sort.desc?\'↓\':\'↑\'):\'↕\'}</span></button>:c.label}</th>')
